package io.atlas.modules.market.service;
import io.atlas.modules.market.repository.MarketRepository;
import io.atlas.modules.market.repository.MarketRepository.*;
import io.atlas.modules.market.model.MarketPolicy;import io.atlas.modules.market.model.MarketBrowse;
import io.atlas.modules.auth.AuthModule;
import io.atlas.modules.rank.RankModule;
import net.minecraft.server.MinecraftServer;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.network.chat.Component;
import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;
public final class MarketService {
 private final MarketRepository repository=new MarketRepository();private final MarketAssets assets=new MarketAssets();private final io.atlas.modules.research.service.ResearchMoneyService money=new io.atlas.modules.research.service.ResearchMoneyService();
 private final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor(r->{var t=new Thread(r,"atlas-market");t.setDaemon(true);return t;});private MinecraftServer server;private final Set<UUID> busy=ConcurrentHashMap.newKeySet();
 public void start(MinecraftServer server){this.server=server;worker.scheduleWithFixedDelay(this::poll,5,3,TimeUnit.SECONDS);}
 private <T>T main(Supplier<T> action)throws Exception{var f=new CompletableFuture<T>();server.execute(()->{try{f.complete(action.get());}catch(Throwable e){f.completeExceptionally(e);}});return f.get(20,TimeUnit.SECONDS);}
 private ServerPlayer player(UUID id){if(id==null)return null;var p=server.getPlayerList().getPlayer(id);return p!=null&&!p.hasDisconnected()&&AuthModule.getAuthService().isAuthenticated(id)?p:null;}
 public boolean eligible(ServerPlayer p){return p!=null&&AuthModule.getAuthService().isAuthenticated(p.getUUID())&&!p.isCreative()&&!p.isSpectator()&&com.cobblemon.mod.common.battles.BattleRegistry.getBattleByParticipatingPlayer(p)==null;}
 private void message(UUID id,String text){server.execute(()->{var p=player(id);if(p!=null)p.sendSystemMessage(Component.literal(text));});}
 private void request(ServerPlayer p,Runnable action){if(!AuthModule.getAuthService().isAuthenticated(p.getUUID())||!busy.add(p.getUUID()))return;worker.execute(()->{try{action.run();}catch(Exception e){message(p.getUUID(),"§cOperação temporariamente indisponível. Atualize o mercado antes de tentar novamente.");io.atlas.AtlasMod.LOGGER.warn("Operação de mercado pendente",e);}finally{busy.remove(p.getUUID());}});}
 public int open(ServerPlayer p,String kind,boolean own,int page,String search){return open(p,MarketBrowse.defaults(kind,own,page,search));}
 public int open(ServerPlayer p,MarketBrowse browse){request(p,()->{var listings=repository.list(browse,browse.own()?p.getUUID():null);server.execute(()->{var current=player(p.getUUID());if(current!=null)current.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inventory,viewer)->new io.atlas.modules.market.menu.MarketMenu(id,inventory,browse,listings,null,null),Component.literal("GTS • "+(browse.kind().equals("ALL")?"Itens e Pokémon":browse.kind().equals("ITEM")?"Itens":"Pokémon"))));});});return 1;}
 public int maximumSeconds(ServerPlayer p){return MarketPolicy.maxSeconds(RankModule.getRankService().getPlayerRanks(p.getUUID()).stream().map(rank->rank.getIdentifier()).toList());}
 public void chooseItem(ServerPlayer p){if(canAnnounce(p))p.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inventory,viewer)->new io.atlas.modules.market.menu.MarketItemSelectMenu(id,inventory),Component.literal("GTS • Selecionar item")));}
 public void priceSelectedItem(ServerPlayer p,net.minecraft.world.item.ItemStack selected){if(!canAnnounce(p))return;((io.atlas.mixin.PlayerListSaveInvoker)server.getPlayerList()).atlas$savePlayer(p);wizard(p,io.atlas.modules.market.menu.MarketAnnounceMenu.Stage.PRICE,assets.itemDraft(p,selected,100));}
 private boolean canAnnounce(ServerPlayer p){if(eligible(p))return true;p.sendSystemMessage(Component.literal("§cUse Survival, faça login e termine a batalha antes de anunciar."));return false;}
 private void wizard(ServerPlayer p,io.atlas.modules.market.menu.MarketAnnounceMenu.Stage stage,Draft draft){p.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inventory,viewer)->new io.atlas.modules.market.menu.MarketAnnounceMenu(id,inventory,stage,draft),Component.literal(switch(stage){case TYPE->"GTS • Anunciar";case PARTY->"GTS • Escolher Pokémon";case PRICE->"GTS • Definir preço";})));}
 public void announce(ServerPlayer p){if(canAnnounce(p))wizard(p,io.atlas.modules.market.menu.MarketAnnounceMenu.Stage.TYPE,null);}
 public void choosePokemon(ServerPlayer p){if(canAnnounce(p))wizard(p,io.atlas.modules.market.menu.MarketAnnounceMenu.Stage.PARTY,null);}
 public void priceItem(ServerPlayer p){if(!canAnnounce(p))return;try{wizard(p,io.atlas.modules.market.menu.MarketAnnounceMenu.Stage.PRICE,assets.draft(p,"ITEM",0,100));}catch(IllegalArgumentException e){p.sendSystemMessage(Component.literal("§c"+e.getMessage()));announce(p);}}
 public void pricePokemon(ServerPlayer p,UUID pokemon){if(!canAnnounce(p))return;var party=com.cobblemon.mod.common.Cobblemon.INSTANCE.getStorage().getParty(p);for(int i=0;i<6;i++)if(party.get(i)!=null&&party.get(i).getUuid().equals(pokemon)){try{wizard(p,io.atlas.modules.market.menu.MarketAnnounceMenu.Stage.PRICE,assets.draft(p,"POKEMON",i+1,100));}catch(IllegalArgumentException e){p.sendSystemMessage(Component.literal("§c"+e.getMessage()));choosePokemon(p);}return;}p.sendSystemMessage(Component.literal("§cEsse Pokémon não está mais na sua equipe. Escolha novamente."));choosePokemon(p);}
 public void review(ServerPlayer p,Draft draft){if(!canAnnounce(p)||!draft.seller().equals(p.getUUID())||!MarketPolicy.price(draft.price()))return;if(draft.durationSeconds()>maximumSeconds(p)){p.sendSystemMessage(Component.literal("§cA duração excede o limite atual do seu cargo."));return;}p.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inventory,viewer)->new io.atlas.modules.market.menu.MarketMenu(id,inventory,draft.kind(),false,0,"",List.of(),draft,null),Component.literal("Confirmar anúncio")));}
 public int draft(ServerPlayer p,String kind,int slot,long price){return draft(p,kind,slot,price,86400);}
 public int draft(ServerPlayer p,String kind,int slot,long price,int seconds){if(seconds<1||seconds>maximumSeconds(p)){p.sendSystemMessage(Component.literal("§cPrazo máximo do seu cargo: "+MarketPolicy.duration(maximumSeconds(p))+"."));return 0;}if(!eligible(p)){p.sendSystemMessage(Component.literal("§cUse Survival, faça login e termine a batalha antes de anunciar."));return 0;}if(!MarketPolicy.price(price))return 0;try{var draft=assets.draft(p,kind,slot,price).duration(seconds);p.openMenu(new net.minecraft.world.SimpleMenuProvider((id,inventory,viewer)->new io.atlas.modules.market.menu.MarketMenu(id,inventory,kind,false,0,"",List.of(),draft,null),Component.literal("Confirmar anúncio")));return 1;}catch(Exception e){p.sendSystemMessage(Component.literal("§c"+e.getMessage()));return 0;}}
 public int draftItem(ServerPlayer p,int quantity,long price,int seconds){if(!canAnnounce(p))return 0;var hand=p.getMainHandItem();if(quantity<1||quantity>hand.getCount()){p.sendSystemMessage(Component.literal("§cA quantia deve estar entre 1 e o total de itens na sua mão."));return 0;}if(seconds<1||seconds>maximumSeconds(p)){p.sendSystemMessage(Component.literal("§cPrazo máximo do seu cargo: "+MarketPolicy.duration(maximumSeconds(p))+"."));return 0;}if(!MarketPolicy.price(price))return 0;var selection=hand.copyWithCount(quantity);review(p,assets.itemDraft(p,selection,price).duration(seconds));return 1;}
 public void publish(ServerPlayer p,Draft draft){if(!eligible(p)||!draft.seller().equals(p.getUUID()))return;if(draft.durationSeconds()>maximumSeconds(p)){p.sendSystemMessage(Component.literal("§cEscolha uma duração dentro do limite atual do seu cargo."));return;}int limit=MarketPolicy.limit(RankModule.getRankService().getPlayerRanks(p.getUUID()).stream().map(r->r.getIdentifier()).toList());p.closeContainer();request(p,()->{if(!repository.prepare(draft,limit)){message(p.getUUID(),"§cLimite de anúncios atingido ou Pokémon já anunciado. Seu limite é "+limit+" no GTS.");return;}message(p.getUUID(),"§ePreparando anúncio e guardando o bem em custódia...");});}
 public void inspect(ServerPlayer p,UUID id,String kind,boolean own){inspect(p,id,MarketBrowse.defaults(kind,own,0,""));}
 public void inspect(ServerPlayer p,UUID id,MarketBrowse browse){request(p,()->{var listing=repository.find(id).orElse(null);if(listing==null||!browse.kind().equals("ALL")&&!listing.kind().equals(browse.kind())||browse.own()&&!listing.seller().equals(p.getUUID()))return;server.execute(()->{var current=player(p.getUUID());if(current!=null)current.openMenu(new net.minecraft.world.SimpleMenuProvider((menu,inventory,viewer)->new io.atlas.modules.market.menu.MarketMenu(menu,inventory,browse,List.of(),null,listing),Component.literal("Detalhes do anúncio")));});});}
 public void buy(ServerPlayer p,UUID id){if(!eligible(p)){p.sendSystemMessage(Component.literal("§cUse Survival e termine a batalha antes de comprar."));return;}p.closeContainer();request(p,()->{var l=repository.find(id).orElse(null);if(l==null||!l.state().equals("ACTIVE")||l.seller().equals(p.getUUID())){message(p.getUUID(),"§cAnúncio indisponível ou pertencente a você.");return;}boolean ready;try{ready=main(()->{var current=player(p.getUUID());if(!eligible(current))return false;try{return money.balance(current).compareTo(java.math.BigInteger.valueOf(l.price()))>=0&&assets.space(current,l.kind());}catch(Exception e){throw new IllegalStateException(e);}});}catch(Exception e){throw new IllegalStateException(e);}if(!ready){message(p.getUUID(),"§cVerifique seu saldo e espaço no inventário/equipe/PC.");return;}if(repository.buy(id,p.getUUID()))message(p.getUUID(),"§eCompra confirmada. Processando cobrança e entrega...");else message(p.getUUID(),"§cEste anúncio já foi comprado ou cancelado.");});}
 public void cancel(ServerPlayer p,UUID id){if(!eligible(p))return;p.closeContainer();request(p,()->message(p.getUUID(),repository.cancel(id,p.getUUID())?"§eCancelamento solicitado. O bem será devolvido ao seu inventário/equipe/PC.":"§cAnúncio já vendido, cancelado ou em processamento."));}
 public void withdraw(ServerPlayer p,String kind){request(p,()->{int count=repository.withdraw(p.getUUID(),kind);message(p.getUUID(),count>0?"§eRetirada solicitada para "+count+" venda(s). Confira /saldo.":"§7Nenhum ganho disponível para retirar neste mercado.");});}
 private void clear(UUID id,String prefix,UUID listing){server.execute(()->{var p=player(id);if(p!=null){p.removeTag(prefix+listing);((io.atlas.mixin.PlayerListSaveInvoker)p.getServer().getPlayerList()).atlas$savePlayer(p);}});}
 private MarketAssets.Saved escrow(Listing l,boolean recovering)throws Exception{return main(()->{var p=player(l.seller());if(!eligible(p))return null;try{return assets.escrow(l,p,recovering);}catch(Exception e){throw new IllegalStateException(e);}});}
 private MarketAssets.Saved deliver(Listing l,UUID receiver,boolean recovering)throws Exception{return main(()->{var p=player(receiver);if(!eligible(p))return null;try{return assets.deliver(l,p,recovering);}catch(Exception e){throw new IllegalStateException(e);}});}
 private void barriers(MarketAssets.Saved saved)throws Exception{for(var future:saved.barriers())future.get(20,TimeUnit.SECONDS);}
 private void process(Listing l)throws Exception{
  if(l.state().equals("PREPARING")||l.state().equals("ESCROWING")){boolean recovery=l.state().equals("ESCROWING");if(!main(()->eligible(player(l.seller()))))return;if(!recovery&&!repository.transition(l.id(),"PREPARING","ESCROWING"))return;var saved=escrow(l,recovery);if(saved==null){if(!recovery)repository.transition(l.id(),"ESCROWING","PREPARING");return;}barriers(saved);main(()->{var p=player(l.seller());if(p==null)throw new IllegalStateException("Seller disconnected before escrow receipt");try{assets.receipt(l,p);return true;}catch(Exception e){throw new IllegalStateException(e);}});if(repository.transition(l.id(),"ESCROWING","ACTIVE")){clear(l.seller(),"atlasMarketEscrow:",l.id());message(l.seller(),"§aAnúncio publicado: §f"+l.name()+" §apor "+MarketPolicy.formatPrice(l.price())+" CobbleDollars.");}return;}
  if(l.state().equals("DEBITING")||l.state().equals("PAYING")){boolean recovery=l.state().equals("PAYING");if(!main(()->eligible(player(l.buyer()))))return;if(!recovery&&!repository.transition(l.id(),"DEBITING","PAYING"))return;boolean moved=main(()->{var p=player(l.buyer());if(!eligible(p))return false;try{return money.move(p,l.id(),l.price(),"atlasMarketDebit:",true,recovery);}catch(Exception e){throw new IllegalStateException(e);}});if(!moved){if(!recovery)repository.transition(l.id(),"PAYING","DEBITING");return;}if(repository.transition(l.id(),"PAYING","DEBITED"))clear(l.buyer(),"atlasMarketDebit:",l.id());return;}
  if(Set.of("DEBITED","DELIVERING","CANCEL_REQUESTED","RETURNING").contains(l.state())){boolean returning=l.state().equals("CANCEL_REQUESTED")||l.state().equals("RETURNING");String before=returning?"CANCEL_REQUESTED":"DEBITED",during=returning?"RETURNING":"DELIVERING";UUID receiver=returning?l.seller():l.buyer();if(!main(()->eligible(player(receiver))))return;boolean recovering=l.state().equals(during);if(!recovering&&!repository.transition(l.id(),before,during))return;var saved=deliver(l,receiver,recovering);if(saved==null){if(!recovering)repository.transition(l.id(),during,before);return;}barriers(saved);if(repository.transition(l.id(),during,returning?"CANCELLED":"SOLD")){server.execute(()->{var p=player(receiver);if(p!=null)assets.clearDelivery(l,p);});message(receiver,returning?("EXPIRED".equals(l.endReason())?"§eAnúncio expirado. Bem devolvido ao inventário/equipe/PC.":"§aBem devolvido. Anúncio cancelado."):"§aCompra recebida: §f"+l.name()+"§a. Confira seu inventário/equipe/PC.");}return;}
  if(l.state().equals("SOLD")&&(l.credit().equals("PENDING")||l.credit().equals("PAYING"))){boolean recovery=l.credit().equals("PAYING");if(!main(()->player(l.seller())!=null))return;if(!recovery&&!repository.credit(l.id(),"PENDING","PAYING"))return;boolean moved=main(()->{var p=player(l.seller());if(p==null)return false;try{return money.move(p,l.id(),l.price(),"atlasMarketCredit:",false,recovery);}catch(Exception e){throw new IllegalStateException(e);}});if(!moved&&!recovery)repository.credit(l.id(),"PAYING","PENDING");if(moved&&repository.credit(l.id(),"PAYING","PAID")){clear(l.seller(),"atlasMarketCredit:",l.id());message(l.seller(),"§aVenda concluída! Você recebeu §f"+MarketPolicy.formatPrice(l.price())+" CobbleDollars §apor "+l.name()+".");}}
 }
 private void poll(){try{repository.expire();for(var old:repository.unclassified()){try{var metadata=main(()->assets.metadata(old,server));repository.classify(old.id(),metadata[0],Integer.parseInt(metadata[1]));}catch(Exception error){repository.classify(old.id(),"OTHER",0);io.atlas.AtlasMod.LOGGER.warn("GTS: ficha antiga {} sem classificação nativa",old.id(),error);}}for(var l:repository.pending()){try{process(l);}catch(Exception error){Throwable cause=error;while(cause.getCause()!=null)cause=cause.getCause();String message=cause.getMessage();var current=repository.find(l.id()).orElse(l);if("SOURCE_CHANGED".equals(message)){repository.transition(l.id(),"ESCROWING","VOID");message(l.seller(),"§cO item/Pokémon mudou antes da confirmação. Anúncio cancelado sem retirada.");}else if("INSUFFICIENT_FUNDS".equals(message)){repository.transition(l.id(),"PAYING","ACTIVE");message(l.buyer(),"§cSaldo insuficiente. A compra não foi cobrada.");}else if(Set.of("UNCERTAIN_PAYMENT","UNCERTAIN_ESCROW","UNCERTAIN_DELIVERY").contains(message==null?"":message)){if(current.state().equals("SOLD"))repository.credit(l.id(),"PAYING","REVIEW");else repository.transition(l.id(),current.state(),"REVIEW");message(l.seller(),"§cOperação de mercado aguardando conferência da staff.");}io.atlas.AtlasMod.LOGGER.warn("Mercado: operação {} preservada para retry/conferência",l.id(),error);}}}catch(Exception e){io.atlas.AtlasMod.LOGGER.warn("Fila de mercado temporariamente indisponível",e);}}
 public void stop(){worker.shutdownNow();}
}
